<script>const CSRF=<?=json_encode($csrf)?>;const profileLanguage=<?=json_encode($language)?>;const region=<?=json_encode($region)?>;const p=<?=json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const hints={yookassa:'ЮKassa: используйте URL магазина/платёжной страницы. Для автоматического подтверждения подключается webhook payment.succeeded.',robokassa:'Robokassa: укажите вашу платёжную форму. Успешный платёж подтверждается через ResultURL.',cloudpayments:'CloudPayments: укажите вашу платёжную страницу. Подтверждение — через callback/webhook.',bank:'Банк / СБП: вставьте собственную ссылку. Автоматическая проверка зависит от вашего банка.',payment_link:'Любая HTTPS-ссылка на вашу страницу оплаты.'};function q(id){return document.getElementById(id)}function hint(){q('hint_ru').textContent=hints[q('payment_method_ru').value]||''}q('payment_method_ru').value=p.payment_method_ru||'yookassa';q('payment_method_intl').value='paypal';q('currency').value=p.currency||'RUB';hint();q('payment_method_ru').onchange=hint;q('save').onclick=async()=>{const b={title:q('title').value,description:q('description').value,currency:q('currency').value,min_amount:q('min_amount').value,max_amount:q('max_amount').value,payment_method_ru:q('payment_method_ru').value,payment_url_ru:q('payment_url_ru').value,payment_method_intl:'paypal',payment_url_intl:q('payment_url_intl').value,overlay_title:q('overlay_title').value,overlay_duration:q('overlay_duration').value,overlay_template:q('overlay_template').value};const r=await fetch('/api/donation_profile.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(b)});const d=await r.json();q('status').textContent=d.ok?'✓ Настройки сохранены':'Ошибка: '+(d.error||'неизвестная ошибка');if(d.ok)q('public_url').value=d.public_url};</script></body></html>
